<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';learning_require_login();$pdo=learning_pdo();$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT * FROM learning_quizzes WHERE id=?");$s->execute([$id]);$quiz=$s->fetch();if(!$quiz)exit('Quiz not found.');$s=$pdo->prepare("SELECT * FROM learning_questions WHERE quiz_id=? ORDER BY sort_order");$s->execute([$id]);$qs=$s->fetchAll();$s=$pdo->prepare("SELECT * FROM learning_options WHERE question_id IN(SELECT id FROM learning_questions WHERE quiz_id=?) ORDER BY sort_order");$s->execute([$id]);$opts=[];foreach($s as $o)$opts[$o['question_id']][]=$o;
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=eh($quiz['title'])?></title><style>body{margin:0;background:#080a10;color:#fff;font-family:Inter,system-ui}.wrap{max-width:850px;margin:auto;padding:30px 18px}.card{padding:22px;border:1px solid #fff1;border-radius:15px;background:#10151e}.q{padding:14px 0;border-bottom:1px solid #fff1}.opt{display:block;padding:9px;border:1px solid #fff1;border-radius:8px;margin:5px 0;font-size:9px;color:#b7c0ce}.btn{padding:11px 14px;border:0;border-radius:8px;background:linear-gradient(135deg,#8b5cf6,#22d3ee);color:#fff;font-weight:850;font-size:9px;margin-top:15px}.result{font-size:10px;margin-top:15px}</style></head><body><div class="wrap"><a href="quiz.php" style="font-size:8px;color:#a78bfa">← Quizzes</a><div class="card"><h1><?=eh($quiz['title'])?></h1><p style="font-size:8px;color:#788398"><?=eh($quiz['description'])?></p><form id="f"><?php foreach($qs as $i=>$q):?><div class="q"><strong style="font-size:10px"><?=$i+1?>. <?=eh($q['question'])?></strong><?php foreach($opts[$q['id']]??[] as $o):?><label class="opt"><input type="radio" name="q[<?=$q['id']?>]" value="<?=$o['id']?>"> <?=eh($o['option_text'])?></label><?php endforeach;?></div><?php endforeach;?><button class="btn">Submit</button></form><div id="r" class="result"></div></div></div><script>f.onsubmit=async e=>{e.preventDefault();let a={};new FormData(f).forEach((v,k)=>{let m=k.match(/q\[(\d+)\]/);if(m)a[m[1]]=v});let r=await fetch('quiz-api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({quiz_id:<?=$id?>,answers:a})});let x=await r.json();document.getElementById('r').textContent=x.ok?`Score ${x.score}/${x.total} · ${x.percent}% · ${x.passed?'PASSED':'FAILED'} · +${x.xp} XP`:x.error}</script></body></html>